    window.previousSlide = function(){ if(index > 0){ index--; render(); }};
    document.addEventListener('keydown', (e)=>{
      if(['ArrowRight','PageDown',' '].includes(e.key)){ e.preventDefault(); nextSlide(); }
      if(['ArrowLeft','PageUp'].includes(e.key)){ e.preventDefault(); previousSlide(); }
      if(e.key === 'Home'){ goToSlide(0); }
      if(e.key === 'End'){ goToSlide(total-1); }
